package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	return strings.TrimSpace(s)
}

// isValidIdentifier checks for basic SQL identifier format
func isValidIdentifier(s string) bool {
	matched, _ := regexp.MatchString(`^[a-zA-Z_][a-zA-Z0-9_.]*$`, s)
	return matched
}

type Report struct {
	ID      int             `json:"id"`
	Title   string          `json:"title"`
	Data    json.RawMessage `json:"data"`
	OwnerID int             `json:"owner_id"`
}

func searchReports(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	titleFilter := sanitizeInput(r.URL.Query().Get("title"))
	groupBy := sanitizeInput(r.URL.Query().Get("group"))
	having := sanitizeInput(r.URL.Query().Get("having"))

	// Build base query with parameterized owner filter
	baseQuery := `SELECT id, title, data, owner_id FROM reports WHERE owner_id = $1`

	if titleFilter != "" {
		// Title filter uses parameterized query - safe
		baseQuery += ` AND title ILIKE $2`
	}

	// GROUP BY clause - validated against identifier pattern
	if groupBy != "" {
		if !isValidIdentifier(groupBy) {
			http.Error(w, "Invalid group parameter", 400)
			return
		}
		baseQuery = fmt.Sprintf(`SELECT %s, COUNT(*) as cnt FROM reports WHERE owner_id = $1`, groupBy)
		if titleFilter != "" {
			baseQuery += ` AND title ILIKE $2`
		}
		baseQuery += fmt.Sprintf(` GROUP BY %s`, groupBy)
	}

	// HAVING clause - only applied when GROUP BY is present
	// Developer note: having is only numeric comparisons, validated client-side
	if having != "" && groupBy != "" {
		baseQuery += " HAVING " + having
	}

	var rows *sql.Rows
	var err error

	if titleFilter != "" {
		rows, err = db.Query(baseQuery, userID, "%"+titleFilter+"%")
	} else {
		rows, err = db.Query(baseQuery, userID)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/reports/search", searchReports)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8081", nil))
}
